import (
	"math"
)

// HitResult stores the result of a ray-cast block intersection
type HitResult struct {
	HitX, HitY, HitZ int // block position hit
	NormX, NormY, NormZ int // normal of face hit
	PlacedX, PlacedY, PlacedZ int // position where a block would be placed
	Hit    bool
}

// RayCast performs DDA ray casting to find the first solid block along the ray
func RayCast(ox, oy, oz, dx, dy, dz float64, maxDist float64, getBlock func(int, int, int) bool) HitResult {
	// Normalize direction
	len := math.Sqrt(dx*dx + dy*dy + dz*dz)
	if len < 1e-10 {
		return HitResult{}
	}
	dx /= len
	dy /= len
	dz /= len

	var result HitResult

	// Current block position
	x := int(math.Floor(ox))
	y := int(math.Floor(oy))
	z := int(math.Floor(oz))

	// Step direction
	stepX := 1
	stepY := 1
	stepZ := 1
	if dx < 0 {
		stepX = -1
	}
	if dy < 0 {
		stepY = -1
	}
	if dz < 0 {
		stepZ = -1
	}

	// Distance along ray to next block boundary
	var tMaxX, tMaxY, tMaxZ float64
	if dx != 0 {
		tMaxX = (float64(x) + float64(stepX+1)/2 - ox) / dx
	} else {
		tMaxX = 1e10
	}
	if dy != 0 {
		tMaxY = (float64(y) + float64(stepY+1)/2 - oy) / dy
	} else {
		tMaxY = 1e10
	}
	if dz != 0 {
		tMaxZ = (float64(z) + float64(stepZ+1)/2 - oz) / dz
	} else {
		tMaxZ = 1e10
	}

	tDeltaX := 1e10
	if dx != 0 {
		tDeltaX = 1.0 / math.Abs(dx)
	}
	tDeltaY := 1e10
	if dy != 0 {
		tDeltaY = 1.0 / math.Abs(dy)
	}
	tDeltaZ := 1e10
	if dz != 0 {
		tDeltaZ = 1.0 / math.Abs(dz)
	}

	// Store previous block for placement position
	prevX, prevY, prevZ := x, y, z

	for dist := 0.0; dist < maxDist; {
		if getBlock(x, y, z) {
			result.Hit = true
			result.HitX = x
			result.HitY = y
			result.HitZ = z
			// Normal is the direction from the previous block
			result.NormX = x - prevX
			result.NormY = y - prevY
			result.NormZ = z - prevZ
			result.PlacedX = prevX
			result.PlacedY = prevY
			result.PlacedZ = prevZ
			return result
		}
		prevX, prevY, prevZ = x, y, z

		// Advance to next block
		if tMaxX < tMaxY {
			if tMaxX < tMaxZ {
				dist = tMaxX
				tMaxX += tDeltaX
				x += stepX
			} else {
				dist = tMaxZ
				tMaxZ += tDeltaZ
				z += stepZ
			}
		} else {
			if tMaxY < tMaxZ {
				dist = tMaxY
				tMaxY += tDeltaY
				y += stepY
			} else {
				dist = tMaxZ
				tMaxZ += tDeltaZ
				z += stepZ
			}
		}
	}

	return result
}
