			if !(px+radius > float64(placedX) && px-radius < float64(placedX+1) &&
				py+height > float64(placedY) && py < float64(placedY+1) &&
				pz+radius > float64(placedZ) && pz-radius < float64(placedZ+1)) {
				blockTypes := []block.BlockType{
					block.Grass, block.Dirt, block.Stone, block.Sand,
					block.Wood, block.Planks, block.Cobblestone, block.Leaves, block.Snow,
