	for x := 0; x < m.width+2; x++ {
		s += wallStyle.Render("  ")
	}
	s += "\n"

	for y := 0; y < m.height; y++ {
		// Left border
		s += wallStyle.Render("  ")

		for x := 0; x < m.width; x++ {
			p := Point{x, y}
			isSnake := false
			isHead := false
			for i, sp := range m.snake {
				if sp == p {
					isSnake = true
					if i == 0 {
						isHead = true
					}
					break
				}
			}
			switch {
			case isHead:
				s += headStyle.Render("  ")
			case isSnake:
				s += snakeStyle.Render("  ")
			case p == m.food:
				s += foodStyle.Render("  ")
			default:
				s += emptyStyle.Render("  ")
			}
		}

		// Right border
		s += wallStyle.Render("  ")
		s += "\n"
	}

	// Draw bottom border
	for x := 0; x < m.width+2; x++ {
		s += wallStyle.Render("  ")
	}
	s += "\n\n"

	s += lipgloss.NewStyle().Foreground(lipgloss.Color("#888888")).Render(
		"Arrow keys / WASD: Move  |  R/Enter: Restart  |  Q: Quit",
	) + "\n"

	if m.state == StateGameOver {
		s += "\n" + gameOverStyle.Render(fmt.Sprintf("💀 Game Over! Final Score: %d", m.score)) + "\n"
		s += lipgloss.NewStyle().Foreground(lipgloss.Color("#888888")).Render("Press R or Enter to restart") + "\n"
	}

	return s
}

func newModel(w, h int) model {
	centerX := w / 2
	centerY := h / 2
	snake := []Point{
		{centerX, centerY},
		{centerX - 1, centerY},
		{centerX - 2, centerY},
	}
	food := randomFood(w, h, snake)
	return model{
		snake:  snake,
		food:   food,
		dir:    DirRight,
		nextDir: DirRight,
		state:  StatePlaying,
		score:  0,
		width:  w,
		height: h,
	}
}

func main() {
	rand.Seed(time.Now().UnixNano())

	m := newModel(gridWidth, gridHeight)
	p := tea.NewProgram(m, tea.WithAltScreen())

	if _, err := p.Run(); err != nil {
		fmt.Println("Error running game:", err)
		os.Exit(1)
	}
}
