import (
	"fmt"
	"log"
	"math"

	"mcgo/block"
	"mcgo/player"
	"mcgo/render"
	"mcgo/world"

	"github.com/hajimehoshi/ebiten/v2"
	"github.com/hajimehoshi/ebiten/v2/ebitenutil"
)

type Game struct {
	World         *world.World
	Player        *player.Player
	Meshes        map[world.ChunkPos]*render.ChunkMesh
	SelectedSlot  int
	RenderDist    int
	DebugInfo     string
	FrameCount    int
}

func NewGame() *Game {
	g := &Game{
		World:        world.NewWorld(),
		Player:       player.NewPlayer(0, 40, 0),
		Meshes:       make(map[world.ChunkPos]*render.ChunkMesh),
		SelectedSlot: 0,
		RenderDist:   6,
	}

	// Load initial chunks around player
	cx := int(math.Floor(g.Player.X)) >> 4
	cz := int(math.Floor(g.Player.Z)) >> 4
	g.World.LoadRadius(cx, cz, g.RenderDist)

	return g
}

func (g *Game) Update() error {
	g.FrameCount++

	// Handle ESC to release cursor
	if ebiten.IsKeyPressed(ebiten.KeyEscape) {
		ebiten.SetCursorMode(ebiten.CursorModeVisible)
	}

	// Capture cursor on left click
	if ebiten.IsMouseButtonPressed(ebiten.MouseButtonLeft) || ebiten.IsMouseButtonPressed(ebiten.MouseButtonRight) {
		ebiten.SetCursorMode(ebiten.CursorModeCaptured)
	}

	// Handle scroll wheel for hotbar
	_, dy := ebiten.Wheel()
	if dy > 0 {
		g.SelectedSlot = (g.SelectedSlot - 1 + 9) % 9
	} else if dy < 0 {
		g.SelectedSlot = (g.SelectedSlot + 1) % 9
	}

	// Number keys for hotbar selection
	for i := ebiten.Key1; i <= ebiten.Key9; i++ {
		if ebiten.IsKeyPressed(i) {
			g.SelectedSlot = int(i - ebiten.Key1)
		}
	}

	// Update player movement and physics
	dt := 1.0 / 60.0

	// Toggle debug on F3 press once
	if ebiten.IsKeyPressed(ebiten.KeyF3) {
		g.DebugInfo = fmt.Sprintf("F3 Debug: Pos=(%.1f, %.1f, %.1f) Yaw=%.1f Pitch=%.1f Chunks=%d FPS=%.0f",
			g.Player.X, g.Player.Y, g.Player.Z,
			g.Player.Yaw*180/math.Pi, g.Player.Pitch*180/math.Pi,
			len(g.World.GetLoadedChunks()), ebiten.ActualFPS())
	} else if g.FrameCount%60 == 0 {
		// Update FPS periodically
		if g.DebugInfo != "" {
			g.DebugInfo = fmt.Sprintf("F3 Debug: Pos=(%.1f, %.1f, %.1f) Yaw=%.1f Pitch=%.1f Chunks=%d FPS=%.0f",
				g.Player.X, g.Player.Y, g.Player.Z,
				g.Player.Yaw*180/math.Pi, g.Player.Pitch*180/math.Pi,
				len(g.World.GetLoadedChunks()), ebiten.ActualFPS())
		}
	}

	g.Player.Update(dt, func(bx, by, bz int) bool {
		bt := g.World.GetBlock(bx, by, bz)
		return block.IsSolid(bt)
	})

	// Load new chunks based on player position
	cx := int(math.Floor(g.Player.X)) >> 4
	cz := int(math.Floor(g.Player.Z)) >> 4
	g.World.LoadRadius(cx, cz, g.RenderDist)

	// Block interaction on click - left removes, right places
	lx, ly, lz, lhit := g.castRay()
	if ebiten.IsMouseButtonPressed(ebiten.MouseButtonLeft) && lhit {
		g.World.SetBlock(lx, ly, lz, block.Air)
	}
	if ebiten.IsMouseButtonPressed(ebiten.MouseButtonRight) {
		hit := g.castRayInternal()
		if hit.Hit {
			// Place block one step away from player (avoid placing inside self)
			placedX, placedY, placedZ := hit.PlacedX, hit.PlacedY, hit.PlacedZ
			// Don't place inside player
			px, py, pz := int(math.Floor(g.Player.X)), int(math.Floor(g.Player.Y+1.0)), int(math.Floor(g.Player.Z))
			// Check a 2-high region for player
			insidePlayer := false
			for dy := 0; dy < 2; dy++ {
				if placedX == px && placedY == py+dy && placedZ == pz {
					insidePlayer = true
				}
			}
			if !insidePlayer {
				blockTypes := []block.BlockType{
					block.Grass, block.Dirt, block.Stone, block.Sand,
					block.Wood, block.Planks, block.Cobblestone, block.Leaves, block.Snow,
				}
				g.World.SetBlock(placedX, placedY, placedZ, blockTypes[g.SelectedSlot])
			}
		}
	}

	return nil
}

func (g *Game) castRay() (int, int, int, bool) {
	hit := g.castRayInternal()
	return hit.HitX, hit.HitY, hit.HitZ, hit.Hit
}

func (g *Game) castRayInternal() player.HitResult {
	lx, ly, lz := g.Player.LookVec()
	return player.RayCast(g.Player.X, g.Player.Y+1.6, g.Player.Z,
		lx, ly, lz, 8.0,
		func(bx, by, bz int) bool {
			bt := g.World.GetBlock(bx, by, bz)
			return block.IsSolid(bt)
		})
}

func (g *Game) Draw(screen *ebiten.Image) {
	px, py, pz := g.Player.X, g.Player.Y+1.6, g.Player.Z
	yaw, pitch := g.Player.Yaw, g.Player.Pitch

	render.DrawWorld(screen, g.World, g.Meshes, px, py, pz, yaw, pitch)
	render.DrawHotbar(screen, g.SelectedSlot)

	if g.DebugInfo != "" {
		ebitenutil.DebugPrint(screen, g.DebugInfo)
	}

	// Instructions
	if g.FrameCount < 120 {
		ebitenutil.DebugPrint(screen, "WASD: Move | Space: Jump | Mouse: Look | Click: Remove/Place | Scroll: Select | ESC: Release cursor | F3: Debug")
	}
}

func (g *Game) Layout(outsideWidth, outsideHeight int) (int, int) {
	return 1024, 768
}

func main() {
	ebiten.SetWindowTitle("MiniCraft - Go Minecraft-like Game")
	ebiten.SetWindowSize(1024, 768)
	ebiten.SetCursorMode(ebiten.CursorModeCaptured)

	game := NewGame()

	if err := ebiten.RunGame(game); err != nil {
		log.Fatal(err)
	}
}
