	BlockGrass
	BlockDirt
	BlockStone
	BlockWood
	BlockLeaves
	BlockSand
	BlockWater
	BlockPlank
	BlockCobblestone
	BlockBedrock
	BlockSnow
	BlockGravel
	MAX_BLOCK_TYPES
)

var BlockChars = []string{
	" ",  // Air
	"▒",  // Grass
	"▒",  // Dirt
	"█",  // Stone
	"▓",  // Wood
	"░",  // Leaves
	"░",  // Sand
	"~",  // Water
