	gridWidth  = 20
	gridHeight = 15
	tickInterval = 150 * time.Millisecond
)

type Point struct {
	X, Y int
}

type Direction int

const (
	DirUp Direction = iota
	DirDown
	DirLeft
	DirRight
)

type GameState int

const (
	StatePlaying GameState = iota
	StateGameOver
)

type model struct {
	snake    []Point
	food     Point
	dir      Direction
	nextDir  Direction
	state    GameState
	score    int
	width    int
	height   int
}

func (m model) Init() tea.Cmd {
	return tickCmd()
}

func tickCmd() tea.Cmd {
	return tea.Tick(tickInterval, func(t time.Time) tea.Msg {
		return tickMsg{}
	})
}

