			if m.dir != DirDown {
				m.nextDir = DirUp
			}
		case "down", "s":
			if m.dir != DirUp {
				m.nextDir = DirDown
			}
		case "left", "a":
			if m.dir != DirRight {
				m.nextDir = DirLeft
			}
		case "right", "d":
			if m.dir != DirLeft {
				m.nextDir = DirRight
			}
