import (
	"math"

	"github.com/hajimehoshi/ebiten/v2"
)

// Camera represents a first-person camera
type Camera struct {
	X, Y, Z float64
	Yaw     float64 // horizontal rotation in radians
	Pitch   float64 // vertical rotation in radians
	FOV     float64 // field of view in radians
}

// NewCamera creates a new camera with default settings
func NewCamera(x, y, z float64) *Camera {
	return &Camera{
		X:     x,
		Y:     y,
		Z:     z,
		Yaw:   0,
		Pitch: 0,
		FOV:   math.Pi / 3, // 60 degrees
	}
}

// LookVec returns the normalized look direction vector
func (c *Camera) LookVec() (float64, float64, float64) {
	cp := math.Cos(c.Pitch)
	sp := math.Sin(c.Pitch)
	cy := math.Cos(c.Yaw)
	sy := math.Sin(c.Yaw)
	return cy * cp, sp, sy * cp
}

// RightVec returns the right vector
func (c *Camera) RightVec() (float64, float64, float64) {
	cy := math.Cos(c.Yaw)
	sy := math.Sin(c.Yaw)
	return cy, 0, sy
}

// ForwardVec returns the horizontal forward vector
func (c *Camera) ForwardVec() (float64, float64, float64) {
	cy := math.Cos(c.Yaw)
	sy := math.Sin(c.Yaw)
	return sy, 0, -cy
}

// ViewMatrix returns a view matrix as [16]float64 (column-major)
func (c *Camera) ViewMatrix() [16]float64 {
	// Simplified: we just compute forward/right/up
	fX, fY, fZ := c.LookVec()
	rX, rY, rZ := c.RightVec()
	// Up = right x forward
	uX := rY*fZ - rZ*fY
	uY := rZ*fX - rX*fZ
	uZ := rX*fY - rY*fX

	// Column-major 4x4 view matrix
	return [16]float64{
		rX, uX, -fX, 0,
		rY, uY, -fY, 0,
		rZ, uZ, -fZ, 0,
		-(rX*c.X + rY*c.Y + rZ*c.Z),
		-(uX*c.X + uY*c.Y + uZ*c.Z),
		(fX*c.X + fY*c.Y + fZ*c.Z),
		1,
	}
}

// ProjectionMatrix returns a perspective projection matrix
func (c *Camera) ProjectionMatrix(w, h float64, near, far float64) [16]float64 {
	a := w / h
	f := 1.0 / math.Tan(c.FOV/2.0)
	return [16]float64{
		f / a, 0, 0, 0,
		0, f, 0, 0,
		0, 0, (far + near) / (near - far), -1,
		0, 0, (2 * far * near) / (near - far), 0,
	}
}

// Move processes keyboard input for player movement
func (c *Camera) Move(dx, dy, dz float64) {
	c.X += dx
	c.Y += dy
	c.Z += dz
}

// Rotate updates yaw and pitch from mouse delta
func (c *Camera) Rotate(dyaw, dpitch float64) {
	c.Yaw += dyaw
	c.Pitch += dpitch
	if c.Pitch > math.Pi/2-0.01 {
		c.Pitch = math.Pi/2 - 0.01
	}
	if c.Pitch < -math.Pi/2+0.01 {
		c.Pitch = -math.Pi/2 + 0.01
	}
}

// HandleMouse captures and hides cursor
func HandleMouse() {
	ebiten.SetCursorMode(ebiten.CursorModeCaptured)
}
