anager.LipglossColor(colorInputMultilineBorder))\n\tinputPanelTerminalStyle = inputPanelStyle.Copy().\n\t\t\t\tBorderForeground(colorManager.LipglossColor(colorInputTerminal))\n\tselectedProviderStyle = lipgloss.NewStyle().\n\t\t\t\tBackground(colorManager.LipglossColor(colorSelectedProviderBg)).\n\t\t\t\tForeground(colorManager.LipglossColor(colorSelectedProviderFg)).\n\t\t\t\tBold(true)\n\tunselectedProviderStyle = lipgloss.NewStyle().\n\t\t\t\tForeground(colorManager.LipglossColor(colorUnselectedProvider))\n\twizardTitleStyle = lipgloss.NewStyle().\n\t\t\t\tForeground(colorManager.LipglossColor(colorWizardTitle)).\n\t\t\t\tBold(true)\n\twizardPanelStyle = lipgloss.NewStyle().\n\t\t\t\tBorder(lipgloss.NormalBorder()).\n\t\t\t\tBorderForeground(colorManager.LipglossColor(colorWizardBorder)).\n\t\t\t\tPadding(0, 1)\n\tcompletionPanelStyle = lipgloss.NewStyle().\n\t\t\t\tBorder(lipgloss.RoundedBorder()).\n\t\t\t\tBorderForeground(colorManager.LipglossColor(colorWizardBorder)).\n\t\t\t\tPadding(0, 1)\n\n\t// Blockquote styles for tool calls — coloured left border\n\ttoolCallBorderStyle = lipgloss.NewStyle().\n\t\t\t\tBorder(lipgloss.Border{Left: \"│\"}).\n\t\t\t\tBorderForeground(colorManager.LipglossColor(colorLabelTool)).\n\t\t\t\tPaddingLeft(1)\n\n\ttoolResultBorderStyle = lipgloss.NewStyle().\n\t\t\t\tBorder(lipgloss.Border{Left: \"│\"}).\n\t\t\t\tBorderForeground(colorManager.LipglossColor(colorLabelResult)).\n\t\t\t\tPaddingLeft(1)\n\n\ttoolErrorBorderStyle = lipgloss.NewStyle().\n\t\t\t\tBorder(lipgloss.Border{Left: \"│\"}).\n\t\t\t\tBorderForeground(colorManager.LipglossColor(colorLabelError)).\n\t\t\t\tPaddingLeft(1)\n\n\trightCardStyle = lipgloss.NewStyle().\n\t\t\tBorder(lipgloss.RoundedBorder()).\n\t\t\tBorderForeground(colorManager.LipglossColor(colorPanelBorder)).\n\t\t\tPadding(0, 1)\n\tselectedTranscriptLineStyle = lipgloss.NewStyle().\n\t\t\t\t\tBackground(colorManager.LipglossColor(colorSelectionBackground)).\n\t\t\t\t\tForeground(colorManager.LipglossColor(colorSelectionForeground))\n)\n\n// 这些常量控制光标动画节奏、输入框高度、边框尺寸和主题色。\nconst (\n\tcursorFrameInterval            = time.Second / 30\n\tcursorCycleDuration            = 3 * time.Second\n\tcursorHiddenThreshold          = 0.03\n\tinputMaxVisibleLines           = 10\n\tcontextMeterDefaultWidth       = 80\n\tcontextMeterMinimumBarCells    = 1\n\ttranscriptPanelHorizontalFrame = 4\n\ttranscriptPanelVerticalFrame   = 2\n\trightCardBorderFrame           = 2\n\trightCardHorizontalPadding     = 2\n\trightCardVerticalFrame         = 2\n\trightSidebarMinWidth           = 20\n)\n","is_error":false},{"tool_use_id":"call_02_4lcChaeBGcJDld8WwW5G0409","content":"// 本文件集中定义 Bubble Tea TUI 的状态类型、内部消息和模型切换向导数据结构。\npackage bubble\n\nimport (\n\t\"context\"\n\t\"github.com/charmbracelet/bubbles/textarea\"\n\t\"github.com/charmbracelet/bubbles/viewport\"\n\t\"gocode/internal/loop\"\n\t\"gocode/internal/model\"\n\t\"gocode/internal/settings\"\n\t\"gocode/internal/subagent\"\n\t\"gocode/internal/ui\"\n\t\"time\"\n)\n\n// entryKind 表示 transcript 中一条消息的来源类别。\ntype entryKind int\n\n// transcript 条目类型常量。\nconst (\n\t// entrySystem 表示系统状态或命令提示消息。\n\tentrySystem entryKind = iota\n\t// entryUser 表示用户输入消息。\n\tentryUser\n\t// entryAssistant 表示 assistant 的模型输出消息。\n\tentryAssistant\n\t// entryThinking 表示模型 thinking 过程消息。\n\tentryThinking\n\t// entryTool 表示工具调用、工具结果或终端命令消息。\n\tentryTool\n\t// entryError 表示错误消息。\n\tentryError\n)\n\n// transcriptEntry 是聊天历史区的一条可渲染记录。\ntype transcriptEntry struct {\n\tkind      entryKind\n\ttitle     string\n\tbody      string\n\tisError   bool // true for tool results with IsError=true\n\ttoolUseID string\n\ttoolName  string\n\tcitations []toolCitation\n\tcreatedAt time.Time\n}\n\ntype toolCitation struct {\n\ttoolUseID string\n\tname      string\n\ttarget    string\n\tstatus    string\n\tpreview   string\n\tisError   bool\n}\n\n// selectionPoint 表示 transcript 渲染结果中的一个显示单元格坐标。\ntype selectionPoint struct {\n\trow int\n\tcol int\n}\n\n// assistantDeltaMsg 表示模型流式输出的一段文本增量。\ntype assistantDeltaMsg string\n\n// thinkingDeltaMsg 表示模型 thinking 流式输出的一段文本增量。\ntype thinkingDeltaMsg string\n\n// toolCallMsg 表示工具调用事件。\ntype toolCallMsg ui.ToolCallEvent\n\n// toolResultMsg 表示工具结果事件。\ntype toolResultMsg ui.ToolResultEvent\n\n// systemEventMsg 表示后台任务等系统事件。\ntype systemEventMsg ui.SystemEvent\n\n// doneMsg 表示当前 assistant 输出已经结束。\ntype doneMsg struct{}\n\n// turnFinishedMsg 表示一轮模型调用已经结束，并携带可能的错误。\ntype turnFinishedMsg struct{ err error }\n\n// shellFinishedMsg 表示一次终端命令执行完成后的结果。\ntype shellFinishedMsg struct {\n\tcommand string\n\tstdout  string\n\tstderr  string\n\terr     error\n}\n\ntype subagentFinishedMsg struct {\n\tresult subagent.Result\n\terr    error\n}\n\n// cursorFrameMsg 驱动自定义光标动画更新一帧。\ntype cursorFrameMsg time.Time\n\n// modelWizardStep 表示 /model 向导当前所处的步骤。\ntype modelWizardStep int\n\n// /model 向导步骤常量。\nconst (\n\t// modelWizardProvider 表示正在选择 provider。\n\tmodelWizardProvider modelWizardStep = iota\n\t// modelWizardConfirm 表示正在确认将要应用的模型配置。\n\tmodelWizardConfirm\n)\n\n// modelProviderOption 描述 /model 向导中的一个 provider 选项。\ntype modelProviderOption struct {\n\tid          string\n\tlabel       string\n\tdescription string\n}\n\n// modelProviderOptions 是当前 TUI 支持切换的 provider 列表。\nvar modelProviderOptions = []modelProviderOption{\n\t{\n\t\tid:          model.ProviderCustom,\n\t\tlabel:       \"custom\",\n\t\tdescription: \"Local or custom OpenAI-compatible endpoint\",\n\t},\n\t{\n\t\tid:          model.ProviderDeepSeek,\n\t\tlabel:       \"deepseek\",\n\t\tdescription: \"DeepSeek official OpenAI-compatible endpoint\",\n\t},\n}\n\n// modelWizard 保存 /model 交互向导的临时 UI 状态。\ntype modelWizard struct {\n\tstep          modelWizardStep\n\tselectedIndex int\n\terr           string\n}\n\ntype settingWizardStep int\n\nconst (\n\tsettingWizardContext settingWizardStep = iota\n\tsettingWizardRunMode\n\tsettingWizardMeterLocation\n\tsettingWizardLimit\n\tsettingWizardConfirm\n)\n\ntype settingOption struct {\n\tlabel       string\n\tdescription string\n\tapply       func(*settings.Config)\n}\n\ntype settingWizard struct {\n\tstep     settingWizardStep\n\tselected map[settingWizardStep]int\n\tdraft    settings.Config\n\terr      string\n}\n\n// contextMeterAnimation 记录 context 进度条从旧 token 用量跳到新用量的短时动画。\ntype contextMeterAnimation struct {\n\tinitialized bool\n\tstartedAt   time.Time\n\tfromUsed    float64\n\tfromCache   float64\n\ttargetUsed  int\n\ttargetCache int\n}\n\n// newModelWizard 根据当前配置创建 provider 选择向导，并默认选中当前 provider。\nfunc newModelWizard(current model.Config) *modelWizard {\n\tselected := 0\n\tfor i, option := range modelProviderOptions {\n\t\tif option.id == current.Provider {\n\t\t\tselected = i\n\t\t\tbreak\n\t\t}\n\t}\n\treturn \u0026modelWizard{step: modelWizardProvider, selectedIndex: selected}\n}\n\n// selectedProvider 返回当前选中的 provider，并在索引越界时进行纠正。\nfunc (w *modelWizard) selectedProvider() modelProviderOption {\n\tif w == nil || len(modelProviderOptions) == 0 {\n\t\treturn modelProviderOption{}\n\t}\n\tif w.selectedIndex \u003c 0 {\n\t\tw.selectedIndex = 0\n\t}\n\tif w.selectedIndex \u003e= len(modelProviderOptions) {\n\t\tw.selectedIndex = len(modelProviderOptions) - 1\n\t}\n\treturn modelProviderOptions[w.selectedIndex]\n}\n\n// sessionsLoadedMsg 携带异步加载完成的会话列表。\ntype sessionsLoadedMsg struct {\n\tsessions []sessionSummaryItem\n\terr      error\n}\n\n// sessionRestoredMsg 携带历史恢复完成的结果。\ntype sessionRestoredMsg struct {\n\tsessionID string\n\terr       error\n}\n\n// fileCompletionLoadedMsg 携带异步加载完成的文件补全列表。\ntype fileCompletionLoadedMsg struct {\n\tsearchDir string   // 对应的搜索目录，用于丢弃过期结果\n\titems     []string // 目录内的全部条目（未过滤）\n\tfiltered  []string // 按前缀过滤后的结果\n\terr       error\n}\n\n// sessionSummaryItem 是 session picker 中的一行显示项。\ntype sessionSummaryItem struct {\n\tsessionID      string\n\tcreatedAt      time.Time\n\tfirstMessage   string\n\ttranscriptSize int64\n}\n\n// appModel 是 Bubble Tea TUI 的唯一状态中心。\ntype appModel struct {\n\tctx                 context.Context\n\trunner              Runner\n\tsessionID           string\n\tmodelConfig         ModelConfigController\n\tsettingsConfig      SettingsController\n\tsubagents           SubagentController\n\tsessionStore        SessionStore\n\tcommandRegistry     *CommandRegistry\n\tqueryGuard          QueryGuard\n\tchatQueue           CommandQueue\n\tcursorAnchor        *terminalCursorAnchor\n\tinput               textarea.Model\n\tviewport            viewport.Model\n\twidth               int\n\theight              int\n\tready               bool\n\trunning             bool\n\trunningTerminal     bool\n\tterminalMode        bool\n\tterminalPreview     bool\n\tshowThinking        bool\n\tselecting           bool\n\tselectionActive     bool\n\tselectionStart      selectionPoint\n\tselectionEnd        selectionPoint\n\tcursorFrameAt       time.Time\n\tturnStartedAt       time.Time\n\tcontextMeter        contextMeterAnimation\n\tpending             []string\n\tinputHistory        []string\n\thistoryIndex        int\n\thistoryDraft        string\n\thistoryDownLock     bool\n\ttranscript          []transcriptEntry\n\tactiveAssistant     int\n\tpendingToolCites    []toolCitation\n\tisGenerating        bool\n\tlastCtrlCAt         time.Time // 追踪双击 Ctrl+C 退出\n\tmodelWizard         *modelWizard\n\tsettingWizard       *settingWizard\n\tsessionPicker       *sessionPicker\n\tcompletion          *completion\n\tpipelineState       pipelineState\n\tpipelineActiveAfter time.Time\n\tsidebarWidth        int // 右侧面板宽度（字符），由 relayout() 计算并存储\n}\n\n// pipelinePhaseStatus 标记单个 pipeline 阶段的状态。\ntype pipelinePhaseStatus int\n\nconst (\n\tphaseStatusPending pipelinePhaseStatus = iota\n\tphaseStatusDone\n\tphaseStatusActive\n\tphaseStatusRetry\n)\n\n// pipelinePhaseEntry 单个阶段的状态快照。\ntype pipelinePhaseEntry struct {\n\tname      string\n\tartifact  string // 相对 .pipeline-workspace/ 的文件名\n\tstatus    pipelinePhaseStatus\n\titeration int\n}\n\n// pipelineState 完整 pipeline 状态快照（每 500ms 轮询更新）。\ntype pipelineState struct {\n\tdetected   bool // 本次 TUI 会话检测到活跃 pipeline\n\tactiveIdx  int  // 当前 active 阶段索引（-1 = none）\n\tglobalIter int  // 全局迭代（来自 execution-report.json.iteration）\n\tdoneCount  int  // 已完成阶段数\n\tphases     [18]pipelinePhaseEntry\n}\n\n// pipelineStateUpdatedMsg 由后台轮询 cmd 发回，携带最新 pipelineState。\ntype pipelineStateUpdatedMsg struct {\n\tstate pipelineState\n}\n\ntype contextStatsProvider interface {\n\tContextStats(limitTokens int, draft string) loop.ContextStats\n}\n","is_error":false}]},"created_at":"2026-06-18T07:38:26.937242Z"}
.ccagent/sessions/5f7917792ffa64dcea73d220ea2b7661/transcript.jsonl:8:{"seq":7,"message":{"role":"assistant","tool_use":{"id":"call_00_vgsqTNDxGf1hJ5p84wav1829","name":"Read","input":{"file_path":"internal/ui/bubble/completion.go"}},"tool_uses":[{"id":"call_00_vgsqTNDxGf1hJ5p84wav1829","name":"Read","input":{"file_path":"internal/ui/bubble/completion.go"}},{"id":"call_01_Z1P7SmfaSWWjtyONmFX20573","name":"Read","input":{"file_path":"internal/ui/bubble/input.go"}}]},"created_at":"2026-06-18T07:38:26.937242Z"}
.ccagent/sessions/5f7917792ffa64dcea73d220ea2b7661/transcript.jsonl:9:{"seq":8,"message":{"role":"user","tool_results":[{"tool_use_id":"call_00_vgsqTNDxGf1hJ5p84wav1829","content":"// 本文件定义 / 命令同步补全和 @ 文件异步补全 TUI 组件。\npackage bubble\n\nimport (\n\t\"fmt\"\n\t\"os\"\n\t\"path/filepath\"\n\t\"strings\"\n\t\"unicode\"\n\t\"unicode/utf8\"\n\n\ttea \"github.com/charmbracelet/bubbletea\"\n)\n\n// completionKind 区分命令补全和文件补全。\ntype completionKind int\n\nconst (\n\tcompletionKindCommand completionKind = iota\n\tcompletionKindFile\n)\n\n// completion 保存补全弹窗的临时 UI 状态。\ntype completion struct {\n\tkind completionKind\n\n\t// 命令补全专用：过滤后的命令列表\n\titems []string\n\n\t// 文件补全专用\n\tatByteIndex   int      // @ 在 input.Value() 中的字节偏移\n\tquery         string   // @ 之后到词尾的完整文本（含路径前缀）\n\tsearchDir     string   // 解析出的搜索目录（用于判断是否需要重载）\n\tprefix        string   // searchDir 内的文件名前缀过滤\n\tallItems      []string // 目录内加载到的全部条目\n\tfilteredItems []string // 按 prefix 过滤后的条目\n\n\tselectedIndex int\n\tloading       bool\n}\n\n// visibleItems 返回当前应展示在弹窗中的候选列表。\nfunc (c *completion) visibleItems() []string {\n\tif c.kind == completionKindFile {\n\t\treturn c.filteredItems\n\t}\n\treturn c.items\n}\n\n// navigateUp 向上移动选中光标。\nfunc (c *completion) navigateUp() {\n\tif c.selectedIndex \u003e 0 {\n\t\tc.selectedIndex--\n\t}\n}\n\n// navigateDown 向下移动选中光标。\nfunc (c *completion) navigateDown() {\n\titems := c.visibleItems()\n\tif c.selectedIndex \u003c len(items)-1 {\n\t\tc.selectedIndex++\n\t}\n}\n\n// ──────────────────────────────────────────────────────────────────────────────\n// 触发检测\n// ──────────────────────────────────────────────────────────────────────────────\n\n// detectAtTrigger 在 value 中找到最末尾的词边界 @ 触发点。\n// 词边界条件：@ 位于字符串开头，或前一个字符为空白符。\n// query 为 @ 之后到字符串末尾的内容；query 内不能含空白符（否则说明词已结束）。\n// 如果未找到满足条件的 @，返回 (-1, \"\")。\nfunc detectAtTrigger(value string) (atByteIndex int, query string) {\n\trunes := []rune(value)\n\tn := len(runes)\n\tif n == 0 {\n\t\treturn -1, \"\"\n\t}\n\n\t// 从末尾向前扫描，找到当前\"词\"的起始位置。\n\t// 词 = 连续的非空白字符序列（位于末尾）。\n\twordStart := n // 默认：末尾是空白，没有当前词\n\tfor i := n - 1; i \u003e= 0; i-- {\n\t\tif unicode.IsSpace(runes[i]) {\n\t\t\twordStart = i + 1\n\t\t\tbreak\n\t\t}\n\t\twordStart = i\n\t}\n\n\tif wordStart \u003e= n {\n\t\treturn -1, \"\" // 当前词为空（末尾是空白）\n\t}\n\n\t// 当前词必须以 @ 开头\n\tif runes[wordStart] != '@' {\n\t\treturn -1, \"\"\n\t}\n\n\t// 词边界：@ 在行首，或前一个字符为空白\n\tif wordStart \u003e 0 \u0026\u0026 !unicode.IsSpace(runes[wordStart-1]) {\n\t\treturn -1, \"\" // @ 紧跟非空白字符，不是词边界（如 \"text@foo\"）\n\t}\n\n\t// 计算 @ 在原始字节串中的偏移\n\tbyteOff := 0\n\tfor _, r := range runes[:wordStart] {\n\t\tbyteOff += utf8.RuneLen(r)\n\t}\n\n\t// query = @ 之后的全部文本\n\tq := string(runes[wordStart+1:])\n\treturn byteOff, q\n}\n\n// ──────────────────────────────────────────────────────────────────────────────\n// 路径解析\n// ──────────────────────────────────────────────────────────────────────────────\n\n// resolveSearchDir 根据 @ 之后的 query 解析搜索目录和文件名前缀。\n//\n//   - @       → (cwd, \"\")\n//   - @foo    → (cwd, \"foo\")\n//   - @sub/   → (cwd/sub, \"\")\n//   - @sub/f  → (cwd/sub, \"f\")\n//   - @~/f    → (HOME, \"f\")\n//   - @/etc/f → (\"/etc\", \"f\")\nfunc resolveSearchDir(query string) (dir, prefix string) {\n\tcwd, _ := os.Getwd()\n\tif cwd == \"\" {\n\t\tcwd = \".\"\n\t}\n\n\tswitch {\n\tcase query == \"\" || query == \".\":\n\t\treturn cwd, \"\"\n\n\tcase query == \"~\":\n\t\thome, _ := os.UserHomeDir()\n\t\treturn home, \"\"\n\n\tcase strings.HasPrefix(query, \"~/\"):\n\t\thome, err := os.UserHomeDir()\n\t\tif err != nil {\n\t\t\treturn cwd, \"\"\n\t\t}\n\t\treturn resolvePathParts(home, query[2:])\n\n\tcase strings.HasPrefix(query, \"/\"):\n\t\treturn resolvePathParts(\"/\", query[1:])\n\n\tdefault:\n\t\treturn resolvePathParts(cwd, query)\n\t}\n}\n\n// resolvePathParts 将 base/rest 分解为 (directory, filePrefix)。\n// 若 rest 含路径分隔符，最后一段作为文件名前缀，其余拼入目录。\nfunc resolvePathParts(base, rest string) (dir, prefix string) {\n\tif rest == \"\" {\n\t\treturn base, \"\"\n\t}\n\tif !strings.Contains(rest, \"/\") {\n\t\treturn base, rest\n\t}\n\tidx := strings.LastIndex(rest, \"/\")\n\treturn filepath.Join(base, rest[:idx]), rest[idx+1:]\n}\n\n// ──────────────────────────────────────────────────────────────────────────────\n// appModel 同步逻辑（在 app.go 的 isTextEditingKey 分支调用）\n// ──────────────────────────────────────────────────────────────────────────────\n\n// syncAtCompletion 检测 @ 触发并更新 m.completion。\n// 需要重新加载文件时返回 tea.Cmd，否则返回 nil。\nfunc (m *appModel) syncAtCompletion() tea.Cmd {\n\t// / 命令补全优先，不与 @ 同时激活\n\tif m.completion != nil \u0026\u0026 m.completion.kind == completionKindCommand {\n\t\treturn nil\n\t}\n\n\tval := m.input.Value()\n\tatIdx, query := detectAtTrigger(val)\n\n\tif atIdx \u003c 0 {\n\t\t// 没有触发点，清除文件补全\n\t\tif m.completion != nil \u0026\u0026 m.completion.kind == completionKindFile {\n\t\t\tm.clearCompletionAndRelayout()\n\t\t}\n\t\treturn nil\n\t}\n\n\tsearchDir, prefix := resolveSearchDir(query)\n\tuseDefault := query == \"\"\n\n\tif m.completion == nil || m.completion.kind != completionKindFile || m.completion.searchDir != searchDir {\n\t\t// 目录发生变化或补全尚未创建：重新加载\n\t\tm.completion = \u0026completion{\n\t\t\tkind:        completionKindFile,\n\t\t\tatByteIndex: atIdx,\n\t\t\tquery:       query,\n\t\t\tsearchDir:   searchDir,\n\t\t\tprefix:      prefix,\n\t\t\tloading:     true,\n\t\t}\n\t\tm.sessionPicker = nil\n\t\treturn loadFilesInDirCmd(searchDir, prefix, useDefault)\n\t}\n\n\t// 同一目录：仅更新前缀和过滤结果\n\tm.completion.atByteIndex = atIdx\n\tm.completion.query = query\n\tm.completion.prefix = prefix\n\tfiltered := filterByPrefix(m.completion.allItems, prefix)\n\tif useDefault \u0026\u0026 len(filtered) \u003e 5 {\n\t\tfiltered = filtered[:5]\n\t}\n\tm.completion.filteredItems = filtered\n\tif m.completion.selectedIndex \u003e= len(filtered) {\n\t\tm.completion.selectedIndex = 0\n\t}\n\treturn nil\n}\n\n// syncCommandCompletion 检测 / 命令补全并更新 m.completion。\nfunc (m *appModel) syncCommandCompletion() {\n\tval := m.input.Value()\n\tif !strings.HasPrefix(val, \"/\") {\n\t\tif m.completion != nil \u0026\u0026 m.completion.kind == completionKindCommand {\n\t\t\tm.clearCompletionAndRelayout()\n\t\t}\n\t\treturn\n\t}\n\tquery := strings.TrimPrefix(val, \"/\")\n\titems := commandCompletionItems(query, m.commandRegistry)\n\tif len(items) == 0 {\n\t\tm.clearCompletionAndRelayout()\n\t\treturn\n\t}\n\tif m.completion == nil || m.completion.kind != completionKindCommand {\n\t\tm.completion = \u0026completion{kind: completionKindCommand, items: items, prefix: query}\n\t} else {\n\t\tm.completion.items = items\n\t\tm.completion.prefix = query\n\t\tif m.completion.selectedIndex \u003e= len(items) {\n\t\t\tm.completion.selectedIndex = 0\n\t\t}\n\t}\n}\n\n// ──────────────────────────────────────────────────────────────────────────────\n// 异步文件加载\n// ──────────────────────────────────────────────────────────────────────────────\n\n// loadFilesInDirCmd 异步列出 searchDir 目录下的条目，用 filePrefix 过滤。\n// useDefault=true 时最多返回前 5 条。\nfunc loadFilesInDirCmd(searchDir, filePrefix string, useDefault bool) tea.Cmd {\n\treturn func() tea.Msg {\n\t\tentries, err := os.ReadDir(searchDir)\n\t\tif err != nil {\n\t\t\treturn fileCompletionLoadedMsg{searchDir: searchDir}\n\t\t}\n\n\t\tvar all []string\n\t\tfor _, e := range entries {\n\t\t\tname := e.Name()\n\t\t\tif strings.HasPrefix(name, \".\") {\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\tif e.IsDir() {\n\t\t\t\tall = append(all, name+\"/\")\n\t\t\t} else {\n\t\t\t\tall = append(all, name)\n\t\t\t}\n\t\t}\n\n\t\tfiltered := filterByPrefix(all, filePrefix)\n\t\tif useDefault \u0026\u0026 filePrefix == \"\" \u0026\u0026 len(filtered) \u003e 5 {\n\t\t\tfiltered = filtered[:5]\n\t\t}\n\n\t\treturn fileCompletionLoadedMsg{\n\t\t\tsearchDir: searchDir,\n\t\t\titems:     all,\n\t\t\tfiltered:  filtered,\n\t\t}\n\t}\n}\n\n// filterByPrefix 筛选以 prefix 开头的条目（大小写不敏感）。\nfunc filterByPrefix(items []string, prefix string) []string {\n\tif prefix == \"\" {\n\t\tout := make([]string, len(items))\n\t\tcopy(out, items)\n\t\treturn out\n\t}\n\tlower := strings.ToLower(prefix)\n\tvar out []string\n\tfor _, item := range items {\n\t\tif strings.HasPrefix(strings.ToLower(item), lower) {\n\t\t\tout = append(out, item)\n\t\t}\n\t}\n\treturn out\n}\n\n// ──────────────────────────────────────────────────────────────────────────────\n// 命令补全构造\n// ──────────────────────────────────────────────────────────────────────────────\n\n// newCommandCompletion 创建命令补全（同步）。\nfunc newCommandCompletion(prefix string, registry *CommandRegistry) *completion {\n\titems := commandCompletionItems(prefix, registry)\n\tif len(items) == 0 {\n\t\treturn nil\n\t}\n\treturn \u0026completion{\n\t\tkind:   completionKindCommand,\n\t\titems:  items,\n\t\tprefix: prefix,\n\t}\n}\n\n// commandCompletionItems 从注册表中筛选匹配前缀的命令名。\nfunc commandCompletionItems(prefix string, registry *CommandRegistry) []string {\n\tif registry == nil {\n\t\treturn nil\n\t}\n\tvar items []string\n\tfor _, name := range registry.order {\n\t\tif prefix == \"\" || strings.HasPrefix(name, \"/\"+prefix) {\n\t\t\titems = append(items, name)\n\t\t}\n\t}\n\treturn items\n}\n\n// ──────────────────────────────────────────────────────────────────────────────\n// 补全确认 — 写回输入框\n// ──────────────────────────────────────────────────────────────────────────────\n\n// applyFileCompletion 将选中文件写回输入框，只替换 @query 段，保留之前的文本。\n// trailingSpace=true（Enter）在路径后追加空格以结束引用；false（Tab）不追加，光标停在路径末尾。\nfunc (m appModel) applyFileCompletion(selected string, trailingSpace bool) appModel {\n\tif m.completion == nil {\n\t\treturn m\n\t}\n\tval := m.input.Value()\n\tatIdx, query := detectAtTrigger(val)\n\tif atIdx \u003c 0 {\n\t\treturn m\n\t}\n\n\tbefore := val[:atIdx]\n\tref := buildAtRef(query, m.completion.searchDir, selected)\n\tsuffix := \"\"\n\tif trailingSpace {\n\t\tsuffix = \" \"\n\t}\n\tm.input.SetValue(before + ref + suffix)\n\tm.input.CursorEnd()\n\tm.relayout()\n\treturn m\n}\n\n// buildAtRef 根据原始 query 和 selected 构造 @path 引用。\n// 保留 query 中的路径前缀（如 @~/ 或 @/），只替换最末的文件名片段。\nfunc buildAtRef(query, searchDir, selected string) string {\n\t// 找到最后一个 / 的位置，保留 @ + 路径前缀\n\tif idx := strings.LastIndex(query, \"/\"); idx \u003e= 0 {\n\t\treturn \"@\" + query[:idx+1] + selected\n\t}\n\t// 没有 / 分隔符，直接 @selected\n\t_ = searchDir\n\treturn \"@\" + selected\n}\n\n// applyCommandCompletion 将命令填入输入框。\nfunc (m appModel) applyCommandCompletion(selected string) appModel {\n\tm.input.SetValue(selected + \" \")\n\tm.input.CursorEnd()\n\treturn m\n}\n\nfunc (m *appModel) clearCompletionAndRelayout() {\n\tif m.completion == nil {\n\t\treturn\n\t}\n\tm.completion = nil\n\tm.relayout()\n}\n\n// ──────────────────────────────────────────────────────────────────────────────\n// 渲染\n// ──────────────────────────────────────────────────────────────────────────────\n\n// renderCompletionBox 渲染补全弹窗（显示在输入框上方）。\nfunc (m appModel) renderCompletionBox() string {\n\tif m.completion == nil {\n\t\treturn \"\"\n\t}\n\twidth := maxInt(32, m.width-2)\n\treturn completionPanelStyle.Width(width).Render(m.renderCompletionContent())\n}\n\n// renderCompletionContent 渲染补全弹窗内容。\nfunc (m appModel) renderCompletionContent() string {\n\tc := m.completion\n\tvar title string\n\tswitch c.kind {\n\tcase completionKindCommand:\n\t\ttitle = wizardTitleStyle.Render(\"Commands\")\n\tcase completionKindFile:\n\t\ttitle = wizardTitleStyle.Render(\"Files\")\n\t}\n\tlines := []string{title}\n\n\tif c.loading {\n\t\tlines = append(lines, \"  Loading...\")\n\t\treturn strings.Join(lines, \"\\n\")\n\t}\n\n\tvisible := c.visibleItems()\n\tif len(visible) == 0 {\n\t\tlines = append(lines, \"  No matches.\")\n\t\treturn strings.Join(lines, \"\\n\")\n\t}\n\n\tmaxVisible := 8\n\tstart := 0\n\tif c.selectedIndex \u003e= maxVisible {\n\t\tstart = c.selectedIndex - maxVisible + 1\n\t}\n\tend := start + maxVisible\n\tif end \u003e len(visible) {\n\t\tend = len(visible)\n\t}\n\n\tfor i := start; i \u003c end; i++ {\n\t\tlabel := visible[i]\n\t\tif i == c.selectedIndex {\n\t\t\tlines = append(lines, selectedProviderStyle.Render(fmt.Sprintf(\"\u003e %s\", label)))\n\t\t} else {\n\t\t\tlines = append(lines, unselectedProviderStyle.Render(fmt.Sprintf(\"  %s\", label)))\n\t\t}\n\t}\n\treturn strings.Join(lines, \"\\n\")\n}\n\n// ──────────────────────────────────────────────────────────────────────────────\n// 兼容占位（避免外部调用编译错误）\n// ──────────────────────────────────────────────────────────────────────────────\n\n// newFileCompletion 兼容旧调用签名。\nfunc newFileCompletion(_ string) *completion {\n\treturn \u0026completion{kind: completionKindFile, loading: true}\n}\n\n// loadFileCompletionCmd 兼容旧调用，加载 cwd 默认 5 个文件。\nfunc loadFileCompletionCmd() tea.Cmd {\n\tcwd, _ := os.Getwd()\n\treturn loadFilesInDirCmd(cwd, \"\", true)\n}\n","is_error":false},{"tool_use_id":"call_01_Z1P7SmfaSWWjtyONmFX20573","content":"// 本文件定义输入框提交、斜杠命令、终端模式和历史输入导航行为。\npackage bubble\n\nimport (\n\t\"github.com/charmbracelet/bubbles/textarea\"\n\ttea \"github.com/charmbracelet/bubbletea\"\n\t\"strings\"\n\t\"time\"\n)\n\n// handleSubmit 处理 Enter 提交，根据输入内容分派到聊天、命令或终端执行路径。\nfunc (m appModel) handleSubmit() (tea.Model, tea.Cmd) {\n\tm.reconcileLegacyRunningState()\n\tvar line string\n\tvar ok bool\n\tm, line, ok = m.consumeSubmittedInput()\n\tif !ok {\n\t\treturn m, nil\n\t}\n\n\tif isExitCommandInput(line) {\n\t\tm.rememberInputHistory(line)\n\t\t_, cmd := m.handleCommand(line)\n\t\treturn m, cmd\n\t}\n\tif line == \"!\" {\n\t\tm.toggleTerminalMode()\n\t\treturn m, nil\n\t}\n\tif m.terminalMode {\n\t\tm.rememberInputHistory(line)\n\t\treturn m.submitShellCommand(line)\n\t}\n\tif command, ok := shellCommandFromBang(line); ok {\n\t\tif m.isWorkRunning() {\n\t\t\tm.addEntry(transcriptEntry{kind: entrySystem, title: \"busy\", body: \"terminal commands are unavailable while a turn is running\"})\n\t\t\treturn m, nil\n\t\t}\n\t\tm.rememberInputHistory(line)\n\t\treturn m.submitShellCommand(command)\n\t}\n\n\tif handled, cmd := m.handleCommand(line); handled {\n\t\treturn m, cmd\n\t}\n\n\tif m.isModelWorkRunning() {\n\t\treturn m.submitSupplement(line), nil\n\t}\n\tif m.isTerminalWorkRunning() {\n\t\tm.addEntry(transcriptEntry{kind: entrySystem, title: \"busy\", body: \"chat is unavailable while a terminal command is running\"})\n\t\treturn m, nil\n\t}\n\n\tm.rememberInputHistory(line)\n\treturn m.startChatTurn(line)\n}\n\nfunc (m appModel) handleQueueSubmit() (tea.Model, tea.Cmd) {\n\tvar line string\n\tvar ok bool\n\tm, line, ok = m.consumeSubmittedInput()\n\tif !ok {\n\t\treturn m, nil\n\t}\n\tif m.isModelWorkRunning() {\n\t\treturn m.queueChatInput(line), nil\n\t}\n\tm.input.SetValue(line)\n\tm.input.CursorEnd()\n\tm.syncInputMode()\n\tm.relayout()\n\treturn m, nil\n}\n\nfunc (m appModel) consumeSubmittedInput() (appModel, string, bool) {\n\tline := strings.TrimSpace(m.input.Value())\n\tif line == \"\" {\n\t\treturn m, \"\", false\n\t}\n\tm.input.Reset()\n\tm.resetHistoryNavigation()\n\tm.syncInputMode()\n\tm.relayout()\n\n\tif continued, text := splitContinuation(line); continued {\n\t\tm.rememberInputHistory(line)\n\t\tm.pending = append(m.pending, text)\n\t\tm.refreshViewport()\n\t\treturn m, \"\", false\n\t}\n\n\tif len(m.pending) \u003e 0 {\n\t\tm.pending = append(m.pending, line)\n\t\tline = strings.Join(m.pending, \"\\n\")\n\t\tm.pending = nil\n\t}\n\treturn m, line, true\n}\n\n// handleCommand 处理内置 TUI 命令。除 exit/quit 外，命令仍要求以斜杠开头。\nfunc (m *appModel) handleCommand(line string) (bool, tea.Cmd) {\n\ttrimmed := strings.TrimSpace(line)\n\tif !strings.HasPrefix(trimmed, \"/\") \u0026\u0026 !isBareExitCommand(trimmed) {\n\t\treturn false, nil\n\t}\n\tif m.commandRegistry == nil {\n\t\tm.commandRegistry = NewCommandRegistry()\n\t}\n\treturn m.commandRegistry.Dispatch(m, line)\n}\n\nfunc isExitCommandInput(line string) bool {\n\ttrimmed := strings.TrimSpace(line)\n\treturn trimmed == \"/exit\" || trimmed == \"/quit\" || isBareExitCommand(trimmed)\n}\n\nfunc isBareExitCommand(line string) bool {\n\treturn line == \"exit\" || line == \"quit\"\n}\n\n// toggleTerminalMode 切换持续终端模式，并在 transcript 中写入状态提示。\nfunc (m *appModel) toggleTerminalMode() {\n\tm.terminalMode = !m.terminalMode\n\tm.pending = nil\n\tm.activeAssistant = -1\n\tm.applyCursorAnimation()\n\tstate := \"terminal mode disabled\"\n\tif m.terminalMode {\n\t\tstate = \"terminal mode enabled\"\n\t}\n\tm.addEntry(transcriptEntry{\n\t\tkind:  entrySystem,\n\t\ttitle: \"terminal\",\n\t\tbody:  state,\n\t})\n}\n\n// isTerminalInputActive 判断当前输入框是否需要展示终端模式视觉状态。\nfunc (m appModel) isTerminalInputActive() bool {\n\treturn m.terminalMode || m.terminalPreview\n}\n\n// hasMultilineInput 判断当前输入是否处于多行输入或续行状态。\nfunc (m appModel) hasMultilineInput() bool {\n\treturn len(m.pending) \u003e 0 || strings.Contains(m.input.Value(), \"\\n\")\n}\n\n// syncInputMode 根据当前文本同步一次性终端预览状态。\nfunc (m *appModel) syncInputMode() {\n\tm.terminalPreview = hasBangPrefix(m.input.Value())\n}\n\n// handleInputVerticalNavigation 让上下键先在多行文本内移动，抵达边界后再切换历史输入。\nfunc (m appModel) handleInputVerticalNavigation(direction int) (tea.Model, tea.Cmd) {\n\tif m.isTerminalWorkRunning() {\n\t\treturn m, nil\n\t}\n\n\tif direction \u003c 0 {\n\t\tif canMoveTextareaUp(m.input) {\n\t\t\treturn m.updateInputWithKey(tea.KeyMsg{Type: tea.KeyUp})\n\t\t}\n\t\tif !textareaCursorAtStart(m.input) {\n\t\t\tm.input.CursorStart()\n\t\t\tm.syncInputMode()\n\t\t\tm.applyCursorAnimation()\n\t\t\treturn m, nil\n\t\t}\n\t\treturn m.handleHistoryNavigation(-1)\n\t}\n\n\tif canMoveTextareaDown(m.input) {\n\t\treturn m.updateInputWithKey(tea.KeyMsg{Type: tea.KeyDown})\n\t}\n\tif !textareaCursorAtEnd(m.input) {\n\t\tm.input.CursorEnd()\n\t\tm.historyDownLock = false\n\t\tm.syncInputMode()\n\t\tm.applyCursorAnimation()\n\t\treturn m, nil\n\t}\n\tif m.historyDownLock \u0026\u0026 m.historyIndex != -1 {\n\t\tm.historyDownLock = false\n\t\treturn m, nil\n\t}\n\treturn m.handleHistoryNavigation(1)\n}\n\nfunc (m appModel) submitSupplement(line string) appModel {\n\tline = strings.TrimSpace(line)\n\tif line == \"\" {\n\t\treturn m\n\t}\n\tm.rememberInputHistory(line)\n\tsubmitter, ok := m.runner.(SupplementSubmitter)\n\tif !ok || !submitter.SubmitSupplement(line) {\n\t\tm.addEntry(transcriptEntry{\n\t\t\tkind:  entrySystem,\n\t\t\ttitle: \"supplement\",\n\t\t\tbody:  \"runner does not support running-turn supplements\",\n\t\t})\n\t\treturn m\n\t}\n\tm.addEntry(transcriptEntry{\n\t\tkind:  entryUser,\n\t\ttitle: \"you (supplement)\",\n\t\tbody:  line,\n\t})\n\treturn m\n}\n\n// startChatTurn records and starts a model turn when the guard is idle.\nfunc (m appModel) startChatTurn(line string) (appModel, tea.Cmd) {\n\tline = strings.TrimSpace(line)\n\tif line == \"\" {\n\t\treturn m, nil\n\t}\n\tif !m.queryGuard.StartModel() {\n\t\tm.addEntry(transcriptEntry{kind: entrySystem, title: \"busy\", body: \"assistant is already running\"})\n\t\treturn m, nil\n\t}\n\tm.addEntry(transcriptEntry{\n\t\tkind:  entryUser,\n\t\ttitle: \"you\",\n\t\tbody:  line,\n\t})\n\tm.turnStartedAt = time.Now()\n\tm.syncRunningFlags()\n\tm.activeAssistant = -1\n\treturn m, runTurnCmd(m.ctx, m.runner, line)\n}\n\n// queueChatInput records a chat input for FIFO execution after the active turn.\nfunc (m appModel) queueChatInput(line string) appModel {\n\tline = strings.TrimSpace(line)\n\tif line == \"\" {\n\t\treturn m\n\t}\n\tm.rememberInputHistory(line)\n\tif m.chatQueue.Enqueue(line) {\n\t\tm.addEntry(transcriptEntry{\n\t\t\tkind:  entryUser,\n\t\t\ttitle: \"you (queued)\",\n\t\t\tbody:  line,\n\t\t})\n\t\tm.addEntry(transcriptEntry{\n\t\t\tkind:  entrySystem,\n\t\t\ttitle: \"queued\",\n\t\t\tbody:  \"queued for next turn\",\n\t\t})\n\t}\n\treturn m\n}\n\n// updateInputWithKey 将按键交给 textarea 处理，并同步输入模式、布局和光标动画。\nfunc (m appModel) updateInputWithKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {\n\tinput, cmd := m.input.Update(msg)\n\tm.input = input\n\tm.syncInputMode()\n\tm.relayout()\n\tm.applyCursorAnimation()\n\treturn m, cmd\n}\n\n// canMoveTextareaUp 判断 textarea 光标是否还能向上移动到上一行或上方可视行。\nfunc canMoveTextareaUp(input textarea.Model) bool {\n\tlineInfo := input.LineInfo()\n\treturn input.Line() \u003e 0 || lineInfo.RowOffset \u003e 0\n}\n\n// canMoveTextareaDown 判断 textarea 光标是否还能向下移动到下一行或下方可视行。\nfunc canMoveTextareaDown(input textarea.Model) bool {\n\tlineInfo := input.LineInfo()\n\treturn input.Line() \u003c input.LineCount()-1 || lineInfo.RowOffset \u003c lineInfo.Height-1\n}\n\n// textareaCursorAtStart 判断 textarea 光标是否位于当前输入的逻辑开头。\nfunc textareaCursorAtStart(input textarea.Model) bool {\n\tif canMoveTextareaUp(input) {\n\t\treturn false\n\t}\n\tlineInfo := input.LineInfo()\n\tcursorLine := input.Line()\n\tcopyInput := input\n\tcopyInput.CursorStart()\n\tstartInfo := copyInput.LineInfo()\n\treturn cursorLine == copyInput.Line() \u0026\u0026\n\t\tlineInfo.RowOffset == startInfo.RowOffset \u0026\u0026\n\t\tlineInfo.ColumnOffset == startInfo.ColumnOffset\n}\n\n// textareaCursorAtEnd 判断 textarea 光标是否位于当前输入的逻辑末尾。\nfunc textareaCursorAtEnd(input textarea.Model) bool {\n\tif canMoveTextareaDown(input) {\n\t\treturn false\n\t}\n\tlineInfo := input.LineInfo()\n\tcursorLine := input.Line()\n\tcopyInput := input\n\tcopyInput.CursorEnd()\n\tendInfo := copyInput.LineInfo()\n\treturn cursorLine == copyInput.Line() \u0026\u0026\n\t\tlineInfo.RowOffset == endInfo.RowOffset \u0026\u0026\n\t\tlineInfo.ColumnOffset == endInfo.ColumnOffset\n}\n\n// handleHistoryNavigation 在输入边界处切换历史记录，并保留进入历史前的草稿。\nfunc (m appModel) handleHistoryNavigation(direction int) (tea.Model, tea.Cmd) {\n\tif m.running || len(m.inputHistory) == 0 {\n\t\treturn m, nil\n\t}\n\n\tif direction \u003c 0 {\n\t\tm.historyDownLock = false\n\t\tif m.historyIndex == -1 {\n\t\t\tm.historyDraft = m.input.Value()\n\t\t\tm.historyIndex = len(m.inputHistory) - 1\n\t\t} else if m.historyIndex \u003e 0 {\n\t\t\tm.historyIndex--\n\t\t}\n\t\tm.input.SetValue(m.inputHistory[m.historyIndex])\n\t\tm.input.CursorEnd()\n\t\tm.syncInputMode()\n\t\tm.relayout()\n\t\tm.applyCursorAnimation()\n\t\treturn m, nil\n\t}\n\n\tif m.historyIndex == -1 {\n\t\treturn m, nil\n\t}\n\tif m.historyIndex \u003c len(m.inputHistory)-1 {\n\t\tm.historyIndex++\n\t\tm.input.SetValue(m.inputHistory[m.historyIndex])\n\t\tm.historyDownLock = true\n\t} else {\n\t\tm.historyIndex = -1\n\t\tm.input.SetValue(m.historyDraft)\n\t\tm.historyDraft = \"\"\n\t\tm.historyDownLock = false\n\t}\n\tm.input.CursorEnd()\n\tm.syncInputMode()\n\tm.relayout()\n\tm.applyCursorAnimation()\n\treturn m, nil\n}\n\n// rememberInputHistory 记录一条非空且不重复的用户输入历史。\nfunc (m *appModel) rememberInputHistory(line string) {\n\tline = strings.TrimSpace(line)\n\tif line == \"\" {\n\t\treturn\n\t}\n\tif len(m.inputHistory) \u003e 0 \u0026\u0026 m.inputHistory[len(m.inputHistory)-1] == line {\n\t\treturn\n\t}\n\tm.inputHistory = append(m.inputHistory, line)\n}\n\n// resetHistoryNavigation 清除当前历史浏览状态，回到普通编辑模式。\nfunc (m *appModel) resetHistoryNavigation() {\n\tm.historyIndex = -1\n\tm.historyDraft = \"\"\n\tm.historyDownLock = false\n}\n\n// submitShellCommand 提交终端命令，先写入 transcript，再异步执行 bash。\nfunc (m appModel) submitShellCommand(command string) (tea.Model, tea.Cmd) {\n\tcommand = strings.TrimSpace(command)\n\tif command == \"\" {\n\t\treturn m, nil\n\t}\n\tif !m.queryGuard.StartTerminal() {\n\t\tm.addEntry(transcriptEntry{kind: entrySystem, title: \"busy\", body: \"terminal commands are unavailable while work is running\"})\n\t\treturn m, nil\n\t}\n\tm.addEntry(transcriptEntry{\n\t\tkind:  entryTool,\n\t\ttitle: \"terminal\",\n\t\tbody:  \"$ \" + command,\n\t})\n\tm.syncRunningFlags()\n\tm.activeAssistant = -1\n\treturn m, runShellCmd(m.ctx, command)\n}\n","is_error":false}]},"created_at":"2026-06-18T07:38:26.937242Z"}
