.ccagent/sessions/133d37b9cc94831572b2d784c396c71e/transcript.jsonl:3:{"seq":2,"message":{"role":"user","tool_results":[{"tool_use_id":"call_00_fCX7G8KzZowdmVMZzsRP4950","content":"package main\n\nimport (\n\t\"fmt\"\n\t\"math/rand\"\n\t\"os\"\n\t\"time\"\n\n\ttea \"github.com/charmbracelet/bubbletea\"\n\t\"github.com/charmbracelet/lipgloss\"\n)\n\nconst (\n\tgridWidth  = 20\n\tgridHeight = 15\n\ttickInterval = 150 * time.Millisecond\n)\n\ntype Point struct {\n\tX, Y int\n}\n\ntype Direction int\n\nconst (\n\tDirUp Direction = iota\n\tDirDown\n\tDirLeft\n\tDirRight\n)\n\ntype GameState int\n\nconst (\n\tStatePlaying GameState = iota\n\tStateGameOver\n)\n\ntype model struct {\n\tsnake    []Point\n\tfood     Point\n\tdir      Direction\n\tnextDir  Direction\n\tstate    GameState\n\tscore    int\n\twidth    int\n\theight   int\n}\n\nfunc (m model) Init() tea.Cmd {\n\treturn tickCmd()\n}\n\nfunc tickCmd() tea.Cmd {\n\treturn tea.Tick(tickInterval, func(t time.Time) tea.Msg {\n\t\treturn tickMsg{}\n\t})\n}\n\ntype tickMsg struct{}\n\nfunc (m model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {\n\tswitch msg := msg.(type) {\n\tcase tea.KeyMsg:\n\t\tswitch msg.String() {\n\t\tcase \"ctrl+c\", \"q\":\n\t\t\treturn m, tea.Quit\n\t\tcase \"up\", \"w\":\n\t\t\tif m.dir != DirDown {\n\t\t\t\tm.nextDir = DirUp\n\t\t\t}\n\t\tcase \"down\", \"s\":\n\t\t\tif m.dir != DirUp {\n\t\t\t\tm.nextDir = DirDown\n\t\t\t}\n\t\tcase \"left\", \"a\":\n\t\t\tif m.dir != DirRight {\n\t\t\t\tm.nextDir = DirLeft\n\t\t\t}\n\t\tcase \"right\", \"d\":\n\t\t\tif m.dir != DirLeft {\n\t\t\t\tm.nextDir = DirRight\n\t\t\t}\n\t\tcase \"r\", \"enter\":\n\t\t\tif m.state == StateGameOver {\n\t\t\t\tm = newModel(m.width, m.height)\n\t\t\t\treturn m, tickCmd()\n\t\t\t}\n\t\t}\n\n\tcase tickMsg:\n\t\tif m.state == StatePlaying {\n\t\t\tm.dir = m.nextDir\n\t\t\thead := m.snake[0]\n\t\t\tvar newHead Point\n\t\t\tswitch m.dir {\n\t\t\tcase DirUp:\n\t\t\t\tnewHead = Point{head.X, head.Y - 1}\n\t\t\tcase DirDown:\n\t\t\t\tnewHead = Point{head.X, head.Y + 1}\n\t\t\tcase DirLeft:\n\t\t\t\tnewHead = Point{head.X - 1, head.Y}\n\t\t\tcase DirRight:\n\t\t\t\tnewHead = Point{head.X + 1, head.Y}\n\t\t\t}\n\n\t\t\t// Wall collision\n\t\t\tif newHead.X \u003c 0 || newHead.X \u003e= m.width || newHead.Y \u003c 0 || newHead.Y \u003e= m.height {\n\t\t\t\tm.state = StateGameOver\n\t\t\t\treturn m, nil\n\t\t\t}\n\n\t\t\t// Self collision\n\t\t\tfor _, p := range m.snake {\n\t\t\t\tif p == newHead {\n\t\t\t\t\tm.state = StateGameOver\n\t\t\t\t\treturn m, nil\n\t\t\t\t}\n\t\t\t}\n\n\t\t\t// Move snake\n\t\t\tm.snake = append([]Point{newHead}, m.snake...)\n\n\t\t\t// Check food\n\t\t\tif newHead == m.food {\n\t\t\t\tm.score++\n\t\t\t\tm.food = randomFood(m.width, m.height, m.snake)\n\t\t\t} else {\n\t\t\t\tm.snake = m.snake[:len(m.snake)-1]\n\t\t\t}\n\n\t\t\treturn m, tickCmd()\n\t\t}\n\t}\n\n\treturn m, nil\n}\n\nfunc randomFood(w, h int, snake []Point) Point {\n\tfor {\n\t\tp := Point{rand.Intn(w), rand.Intn(h)}\n\t\tcollision := false\n\t\tfor _, s := range snake {\n\t\t\tif s == p {\n\t\t\t\tcollision = true\n\t\t\t\tbreak\n\t\t\t}\n\t\t}\n\t\tif !collision {\n\t\t\treturn p\n\t\t}\n\t}\n}\n\nvar (\n\tsnakeStyle  = lipgloss.NewStyle().Background(lipgloss.Color(\"#00ff00\"))\n\tfoodStyle   = lipgloss.NewStyle().Background(lipgloss.Color(\"#ff0000\"))\n\temptyStyle  = lipgloss.NewStyle().Background(lipgloss.Color(\"#1a1a2e\"))\n\theadStyle   = lipgloss.NewStyle().Background(lipgloss.Color(\"#00cc00\"))\n\twallStyle   = lipgloss.NewStyle().Background(lipgloss.Color(\"#16213e\"))\n\tscoreStyle  = lipgloss.NewStyle().Foreground(lipgloss.Color(\"#00ff00\")).Bold(true)\n\ttitleStyle  = lipgloss.NewStyle().Foreground(lipgloss.Color(\"#00ff00\")).Bold(true).MarginBottom(1)\n\tgameOverStyle = lipgloss.NewStyle().Foreground(lipgloss.Color(\"#ff4444\")).Bold(true)\n)\n\nfunc (m model) View() string {\n\tvar s string\n\n\ts += titleStyle.Render(\"🐍 贪吃蛇 Snake Game\") + \"\\n\"\n\ts += scoreStyle.Render(fmt.Sprintf(\"Score: %d\", m.score)) + \"\\n\\n\"\n\n\t// Draw top border\n\tfor x := 0; x \u003c m.width+2; x++ {\n\t\ts += wallStyle.Render(\"  \")\n\t}\n\ts += \"\\n\"\n\n\tfor y := 0; y \u003c m.height; y++ {\n\t\t// Left border\n\t\ts += wallStyle.Render(\"  \")\n\n\t\tfor x := 0; x \u003c m.width; x++ {\n\t\t\tp := Point{x, y}\n\t\t\tisSnake := false\n\t\t\tisHead := false\n\t\t\tfor i, sp := range m.snake {\n\t\t\t\tif sp == p {\n\t\t\t\t\tisSnake = true\n\t\t\t\t\tif i == 0 {\n\t\t\t\t\t\tisHead = true\n\t\t\t\t\t}\n\t\t\t\t\tbreak\n\t\t\t\t}\n\t\t\t}\n\t\t\tswitch {\n\t\t\tcase isHead:\n\t\t\t\ts += headStyle.Render(\"  \")\n\t\t\tcase isSnake:\n\t\t\t\ts += snakeStyle.Render(\"  \")\n\t\t\tcase p == m.food:\n\t\t\t\ts += foodStyle.Render(\"  \")\n\t\t\tdefault:\n\t\t\t\ts += emptyStyle.Render(\"  \")\n\t\t\t}\n\t\t}\n\n\t\t// Right border\n\t\ts += wallStyle.Render(\"  \")\n\t\ts += \"\\n\"\n\t}\n\n\t// Draw bottom border\n\tfor x := 0; x \u003c m.width+2; x++ {\n\t\ts += wallStyle.Render(\"  \")\n\t}\n\ts += \"\\n\\n\"\n\n\ts += lipgloss.NewStyle().Foreground(lipgloss.Color(\"#888888\")).Render(\n\t\t\"Arrow keys / WASD: Move  |  R/Enter: Restart  |  Q: Quit\",\n\t) + \"\\n\"\n\n\tif m.state == StateGameOver {\n\t\ts += \"\\n\" + gameOverStyle.Render(fmt.Sprintf(\"💀 Game Over! Final Score: %d\", m.score)) + \"\\n\"\n\t\ts += lipgloss.NewStyle().Foreground(lipgloss.Color(\"#888888\")).Render(\"Press R or Enter to restart\") + \"\\n\"\n\t}\n\n\treturn s\n}\n\nfunc newModel(w, h int) model {\n\tcenterX := w / 2\n\tcenterY := h / 2\n\tsnake := []Point{\n\t\t{centerX, centerY},\n\t\t{centerX - 1, centerY},\n\t\t{centerX - 2, centerY},\n\t}\n\tfood := randomFood(w, h, snake)\n\treturn model{\n\t\tsnake:  snake,\n\t\tfood:   food,\n\t\tdir:    DirRight,\n\t\tnextDir: DirRight,\n\t\tstate:  StatePlaying,\n\t\tscore:  0,\n\t\twidth:  w,\n\t\theight: h,\n\t}\n}\n\nfunc main() {\n\trand.Seed(time.Now().UnixNano())\n\n\tm := newModel(gridWidth, gridHeight)\n\tp := tea.NewProgram(m, tea.WithAltScreen())\n\n\tif _, err := p.Run(); err != nil {\n\t\tfmt.Println(\"Error running game:\", err)\n\t\tos.Exit(1)\n\t}\n}\n","is_error":false},{"tool_use_id":"call_01_5FxuaIXasRF0zaVnhGvw0341","content":"","is_error":false},{"tool_use_id":"call_02_hbQOHIr9z3qi8b5GQNKB3223","content":"","is_error":false}]},"created_at":"2026-06-18T09:51:09.714339Z"}
