const (
	Gravity     = -24.0
	JumpSpeed   = 8.0
	MoveSpeed   = 5.0
	MouseSensitivity = 0.002
	EyeHeight   = 1.6
)

type Player struct {
	X, Y, Z      float64
	Vx, Vy, Vz   float64
	Yaw          float64
	Pitch        float64
	OnGround     bool
}

func NewPlayer(x, y, z float64) *Player {
	return &Player{
		X: x, Y: y, Z: z,
		Yaw:   0,
		Pitch: 0,
	}
}

// LookVec returns the normalized look direction
func (p *Player) LookVec() (float64, float64, float64) {
	cp := math.Cos(p.Pitch)
	sp := math.Sin(p.Pitch)
	cy := math.Cos(p.Yaw)
	sy := math.Sin(p.Yaw)
	return cy * cp, sp, sy * cp
}

// Update handles keyboard input and physics
func (p *Player) Update(dt float64, isSolid func(int, int, int) bool) {
	// Mouse look
	mx, my := ebiten.CursorPosition()
	cx, cy := ebiten.WindowSize()
	screenCX := float64(cx) / 2
	screenCY := float64(cy) / 2
	dx := float64(mx) - screenCX
	dy := float64(my) - screenCY
	if dx != 0 || dy != 0 {
		p.Yaw += dx * MouseSensitivity
		p.Pitch += dy * MouseSensitivity
		if p.Pitch > math.Pi/2-0.01 {
			p.Pitch = math.Pi/2 - 0.01
		}
		if p.Pitch < -math.Pi/2+0.01 {
			p.Pitch = -math.Pi/2 + 0.01
		}
		// Reset cursor to center
		// cursor re-center handled by SetCursorMode capture
	}

	// Movement input
	var moveX, moveZ float64
	fwdX, _, fwdZ := p.LookVec()
	// Forward direction (projected onto XZ plane)
	fwdLen := math.Sqrt(fwdX*fwdX + fwdZ*fwdZ)
	if fwdLen > 0.001 {
		fwdX /= fwdLen
		fwdZ /= fwdLen
	}
	// Right direction
	rightX := -fwdZ
	rightZ := fwdX

	if ebiten.IsKeyPressed(ebiten.KeyW) {
		moveX += fwdX
		moveZ += fwdZ
	}
	if ebiten.IsKeyPressed(ebiten.KeyS) {
		moveX -= fwdX
		moveZ -= fwdZ
	}
	if ebiten.IsKeyPressed(ebiten.KeyA) {
		moveX -= rightX
		moveZ -= rightZ
	}
	if ebiten.IsKeyPressed(ebiten.KeyD) {
		moveX += rightX
		moveZ += rightZ
	}

	// Normalize horizontal movement
	moveLen := math.Sqrt(moveX*moveX + moveZ*moveZ)
	if moveLen > 0.001 {
		moveX /= moveLen
		moveZ /= moveLen
	}

	// Apply velocity
	p.Vx = moveX * MoveSpeed
	p.Vz = moveZ * MoveSpeed

	// Gravity
	p.Vy += Gravity * dt

	// Jump
	if ebiten.IsKeyPressed(ebiten.KeySpace) {
		if p.OnGround {
			p.Vy = JumpSpeed
			p.OnGround = false
		}
	}

	// Sneak (slow descent)
	if ebiten.IsKeyPressed(ebiten.KeyShift) {
		if !p.OnGround && p.Vy < -2 {
			p.Vy = -2
		}
	}

	// Apply movement with collision
	p.moveWithCollision(dt, isSolid)
}

func (p *Player) moveWithCollision(dt float64, isSolid func(int, int, int) bool) {
	// Player hitbox: 0.6 wide, 1.8 tall
	const (
		radius = 0.3
		height = 1.8
	)
	// Move X
	newX := p.X + p.Vx*dt
	if !collides(newX, p.Y, p.Z, radius, height, isSolid) {
		p.X = newX
	}
	// Move Z
	newZ := p.Z + p.Vz*dt
	if !collides(p.X, p.Y, newZ, radius, height, isSolid) {
		p.Z = newZ
	}
	// Move Y
	newY := p.Y + p.Vy*dt
	if !collides(p.X, newY, p.Z, radius, height, isSolid) {
		p.Y = newY
		p.OnGround = false
	} else {
		if p.Vy < 0 {
			p.OnGround = true
		}
		p.Vy = 0
	}

	// Keep within world bounds
	if p.Y < 1 {
		p.Y = 1
		p.Vy = 0
		p.OnGround = true
	}
}

func collides(x, y, z, radius, height float64, isSolid func(int, int, int) bool) bool {
	minX := int(math.Floor(x - radius))
	maxX := int(math.Floor(x + radius))
	minY := int(math.Floor(y))
	maxY := int(math.Floor(y + height))
	minZ := int(math.Floor(z - radius))
	maxZ := int(math.Floor(z + radius))

	for bx := minX; bx <= maxX; bx++ {
		for by := minY; by <= maxY; by++ {
			for bz := minZ; bz <= maxZ; bz++ {
				if isSolid(bx, by, bz) {
					px0, px1 := x-radius, x+radius
					pz0, pz1 := z-radius, z+radius
					bx0, bx1 := float64(bx), float64(bx+1)
					bz0, bz1 := float64(bz), float64(bz+1)
					py0, py1 := y, y+height
					by0, by1 := float64(by), float64(by+1)
					if px1 > bx0 && px0 < bx1 &&
						pz1 > bz0 && pz0 < bz1 &&
						py1 > by0 && py0 < by1 {
						return true
					}
				}
			}
		}
	}
	return false
}
