}

// TestResolveSessionID_WithExistingFlag 验证传入已存在的 session ID 时原样返回。
func TestResolveSessionID_WithExistingFlag(t *testing.T) {
	dir := t.TempDir()
	store, err := session.NewJSONLStore(dir)
	if err != nil {
		t.Fatalf("NewJSONLStore: %v", err)
