	"time"
)

func main() {
	// Terminal setup
	rawMode, err := enableRawTerminal()
	if err != nil {
		fmt.Println("Warning: cannot enable raw terminal mode:", err)
	}
	if rawMode != nil {
		defer rawMode.Close()
	}

	width, height := 80, 30
	game := NewGame(width, height)
	game.Init()

	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanBytes)

	inputBuf := make([]byte, 0)

	fmt.Print("\033[?25l") // hide cursor
	defer fmt.Print("\033[?25h") // show cursor

	for game.Running {
		game.Render()

		if !scanner.Scan() {
			break
		}
		b := scanner.Bytes()
		if len(b) == 0 {
			continue
		}
		ch := b[0]

		switch ch {
		case 'q':
			game.Running = false
		case 'w', 'W':
			game.MovePlayer(0, 0, -1)
		case 's', 'S':
			game.MovePlayer(0, 0, 1)
		case 'a', 'A':
			game.MovePlayer(-1, 0, 0)
		case 'd', 'D':
			game.MovePlayer(1, 0, 0)
		case ' ':
			game.Jump()
		case 'e':
			game.CycleHotbar()
		case '1':
			game.SelectHotbar(0)
		case '2':
			game.SelectHotbar(1)
		case '3':
			game.SelectHotbar(2)
		case '4':
			game.SelectHotbar(3)
		case '5':
			game.SelectHotbar(4)
		case '6':
			game.SelectHotbar(5)
		case '7':
			game.SelectHotbar(6)
		case '8':
			game.SelectHotbar(7)
		case '9':
			game.SelectHotbar(8)
		case 'f':
			game.PlaceBlock()
		case 'g':
			game.BreakBlock()
		case 'c':
			game.ToggleCreative()
		case 'p':
			game.PrintDebug()
		case 27: // ESC
			game.Running = false
		case 3: // Ctrl+C
			game.Running = false
		case '\n', '\r':
			// Enter - interact (grab item / use)
		case 't':
			// toggle fly
			game.Flying = !game.Flying
		default:
			// accumulate typed commands
			if ch >= 32 && ch <= 126 {
				inputBuf = append(inputBuf, ch)
			}
		}
		if len(inputBuf) > 0 {
			cmd := string(inputBuf)
			if cmd == "seed" {
				fmt.Printf("\nSeed: %d\n", game.Seed)
				inputBuf = inputBuf[:0]
				time.Sleep(500 * time.Millisecond)
			} else if cmd == "pos" {
				fmt.Printf("\nPos: (%.1f, %.1f, %.1f)\n", game.PlayerX, game.PlayerY, game.PlayerZ)
				inputBuf = inputBuf[:0]
				time.Sleep(500 * time.Millisecond)
			} else if cmd == "help" {
				game.ShowHelp()
				inputBuf = inputBuf[:0]
				time.Sleep(2 * time.Second)
			} else if len(cmd) > 10 {
				inputBuf = inputBuf[:0]
			}
		}
	}
}
